-- Customer doors find orders, carts and requests by the account's sign-in email.
-- A changed email is unproven until an email link sent to it opens a session:
-- the change revokes links sent to the old address, so only such a session
-- proves the new one. Sessions open before the change prove only the old one.
CREATE TABLE st_email_changes (operator_id TEXT PRIMARY KEY NOT NULL);
CREATE TABLE st_email_link_sessions (session_id TEXT PRIMARY KEY NOT NULL);
CREATE TRIGGER st_email_changed AFTER UPDATE OF email ON oa_operators WHEN NEW.email IS NOT OLD.email BEGIN
 INSERT OR IGNORE INTO st_email_changes(operator_id) VALUES(NEW.id);
 DELETE FROM st_email_link_sessions WHERE session_id IN (SELECT id FROM oa_sessions WHERE operator_id=NEW.id);
END;
CREATE TRIGGER st_email_link_session AFTER INSERT ON oa_sessions
 WHEN NEW.source_token_id IS NOT NULL AND EXISTS(SELECT 1 FROM st_email_changes WHERE operator_id=NEW.operator_id) BEGIN
 INSERT OR IGNORE INTO st_email_link_sessions(session_id) VALUES(NEW.id);
END;

-- A shopper file holds a place in the waiting allowance until a paid order
-- claims it. The keyed client hash bounds each client's share of that allowance;
-- it is local to this installation and never travels in archives.
ALTER TABLE st_uploads ADD COLUMN client TEXT;
-- Allowance counts and lapse cleanup read only these columns, never the file bytes.
CREATE INDEX st_uploads_waiting ON st_uploads(client,order_id,created_at);

-- An unpaid checkout holds its promotion use and budget only while Stripe could
-- still take its payment. Its order records checkoutExpiredAt once Stripe reports
-- that checkout expired or never created; only then is the hold released. Paid
-- use, refunds and cancellations still never release budget.
DROP TRIGGER st_promotion_allocation_delete;
CREATE TRIGGER st_promotion_allocation_delete BEFORE DELETE ON st_promotion_allocations BEGIN
 SELECT CASE WHEN OLD.status<>'reserved' OR NOT EXISTS(SELECT 1 FROM st_orders o WHERE o.id=OLD.order_id
  AND json_extract(o.value_json,'$.payment') IS NULL AND json_extract(o.value_json,'$.checkoutExpiredAt') IS NOT NULL)
 THEN RAISE(ABORT,'ST_PROMOTION_BUDGET_COMMITTED') END;
END;
CREATE TRIGGER st_promotion_released AFTER DELETE ON st_promotion_allocations BEGIN
 INSERT INTO st_headless_events VALUES('promotion.released.'||OLD.order_id,'promotion',OLD.promotion_id,strftime('%Y-%m-%dT%H:%M:%fZ','now'),
  json_object('id','promotion.released.'||OLD.order_id,'kind','promotion','resourceId',OLD.promotion_id,'occurredAt',strftime('%Y-%m-%dT%H:%M:%fZ','now')));
END;

